      setNewWfName('');
      setNewWfIsDefault(false);
      setStatusMsg({ type: 'success', text: 'Workflow created successfully' });
      setTimeout(() => setStatusMsg(null), 3000);
    } catch (err) {
      setStatusMsg({ type: 'error', text: err.message || 'Failed to create workflow' });
    } finally {
      setIsCreating(false);
    }
  };

